def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Check if metadata is a dictionary
            if metadata is not None and not isinstance(metadata, dict):
                raise TypeError("metadata must be a dictionary")
            # Check if timeout is a float or None
            if timeout is not None and not isinstance(timeout, float):
                raise TypeError("timeout must be a float or None")
            # Check if timeout is negative
            if timeout is not None and timeout < 0:
                raise ValueError("timeout cannot be negative")
            # Apply metadata and timeout to the transaction
            tx = func(*args, **kwargs)
            if metadata is not None:
                tx.metadata = metadata
            if timeout is not None:
                tx.timeout = timeout
            return tx
        return wrapper
    return decorator
```
