def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Initialize a set to store the unique base classes
    unique_bases = set()
    # Iterate over the input list of base classes
    for base in classes:
        # If the base class is not already in the set, add it
        if base not in unique_bases:
            unique_bases.add(base)
    # Return the list of unique base classes in the order they were added
    return list(unique_bases)

