def integral(bins, edges):
    if not isinstance(bins, list):
        raise ValueError("bins must be a list")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list")
    if len(bins) != len(edges) - 1:
        raise ValueError("bins and edges must have the same length")
    if not all(isinstance(x, (int, float)) for x in bins):
        raise ValueError("bins must contain only integers or floats")
    if not all(isinstance(x, (int, float)) for x in edges):
        raise ValueError("edges must contain only integers or floats")
    if not all(edges[i] < edges[i+1] for i in range(len(edges) - 1)):
        raise ValueError("edges must be monotonically increasing")

    integral = 0
    for i in range(len(bins)):
        integral += (edges[i+1] - edges[i]) * bins[i]

    return integral

