def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string or None")
    if not isinstance(verbose, bool):
        raise TypeError("verbose must be a boolean")
    if not isinstance(hide_stderr, bool):
        raise TypeError("hide_stderr must be a boolean")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dictionary or None")

    for command in commands:
        if not isinstance(command, str):
            raise TypeError("command must be a string")
        if not command.strip():
            raise ValueError("command cannot be empty")

    for arg in args:
        if not isinstance(arg, str):
            raise TypeError("arg must be a string")
        if not arg.strip():
            raise ValueError("arg cannot be empty")

    if cwd is not None:
        os.chdir(cwd)

    if env is not None:
        for key, value in env.items():
            os.environ[key] = value

    for command in commands:
        if verbose:
            print(f"Running command: {command}")
        if hide_stderr:
            with open(os.devnull, "w") as devnull:
                subprocess.run(command, shell=True, stdout=subprocess.PIPE, stderr=devnull)
        else:
            subprocess.run(command, shell=True, stdout=subprocess.PIPE)
