def _verify(iface, candidate, tentative=False, vtype=None):
    try:
        if not tentative and not iface.providedBy(candidate):
            raise zope.interface.Invalid("Candidate does not claim to provide the interface")
        for name, spec in iface.namesAndDescriptions():
            if name not in candidate:
                raise zope.interface.Invalid("Candidate does not define the required method {}".format(name))
            if spec.signature is not None and spec.signature != candidate[name].signature:
                raise zope.interface.Invalid("Candidate method {} has an incorrect signature".format(name))
        for name, spec in iface.namesAndDescriptions():
            if name not in candidate:
                raise zope.interface.Invalid("Candidate does not define the required attribute {}".format(name))
        return True
    except zope.interface.Invalid as e:
        raise e
