def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    # Resolve arguments' values from spec
    spec_defaults = {}
    for arg in self.spec.args:
        if arg.default is not None:
            spec_defaults[arg.name] = arg.default

    # Resolve arguments' values from other sources
    for arg in self.spec.args:
        if arg.default is None and arg.name in self.defaults:
            spec_defaults[arg.name] = self.defaults[arg.name]

    return spec_defaults

def get_deprecated_args(self):
